AssistantMessageToolRequest(name='create', tool_call_id='function-call-8f3585d5-1a72-4fb8-aa4f-4339e5df8796', arguments={'file_text': "document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contact-form');
    const statusRegion = document.getElementById('form-status');

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        // Reset previous errors
        const errorMessages = form.querySelectorAll('.error-message');
        errorMessages.forEach(msg => {
            msg.hidden = true;
            msg.textContent = '';
        });

        const inputs = form.querySelectorAll('input');
        inputs.forEach(input => {
            input.removeAttribute('aria-invalid');
            input.removeAttribute('aria-describedby');
            // Re-add helper text for phone if it's there
            if (input.id === 'phone') {
                input.setAttribute('aria-describedby', 'phone-helper');
            }
        });

        const errors = [];

        // Validate Full Name
        const nameInput = document.getElementById('full-name');
        if (!nameInput.value.trim()) {
            errors.push({
                id: 'full-name',
                message: 'Error: Full Name is required.'
            });
        }

        // Validate Email
        const emailInput = document.getElementById('email');
        if (!emailInput.value.trim()) {
            errors.push({
                id: 'email',
                message: 'Error: Email Address is required.'
            });
        } else if (!isValidEmail(emailInput.value)) {
            errors.push({
                id: 'email',
                message: 'Error: Please enter a valid email address.'
            });
        }

        // Phone is optional, but if filled, we could validate it here if needed.
        // For this task, it's optional and we only need helper text.

        if (errors.length > 0) {
            errors.forEach((error, index) => {
                const input = document.getElementById(error.id);
                const errorDiv = document.getElementById(`${error.id.split('-')[1] || error.id}-error`);

                input.setAttribute('aria-invalid', 'true');

                // Construct aria-describedby
                let describedBy = errorDiv.id;
                if (input.id === 'phone') {
                    describedBy += ' phone-helper';
                }
                input.setAttribute('aria-describedby', describedBy);

                errorDiv.textContent = error.message;
                errorDiv.hidden = false;

                // Focus the first error
                if (index === 0) {
                    input.focus();
                }
            });

            statusRegion.textContent = `Form submission failed. There are ${errors.length} errors.`;
        } else {
            // Success
            statusRegion.textContent = 'Success: Your support request has been sent.';
            form.reset();
            // Reset aria-invalid etc.
            inputs.forEach(input => {
                input.removeAttribute('aria-invalid');
                input.removeAttribute('aria-describedby');
                if (input.id === 'phone') {
                    input.setAttribute('aria-describedby', 'phone-helper');
                }
            });
            alert('Thank you! Your request has been submitted.');
        }
    });

    function isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }
});
