        <form id="contact-form" novalidate>
            <div class="form-field">
                <label for="full-name">Full Name <span aria-hidden="true">*</span></label>
                <input type="text" id="full-name" name="full-name" required autocomplete="name">
                <div class="error-message" id="name-error" hidden></div>
            </div>

            <div class="form-field">
                <label for="email">Email Address <span aria-hidden="true">*</span></label>
                <input type="email" id="email" name="email" required autocomplete="email">
                <div class="error-message" id="email-error" hidden></div>
            </div>

            <div class="form-field">
                <label for="phone">Phone Number (Optional)</label>
                <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-helper">
                <p id="phone-helper" class="helper-text">Expected format: +1-123-456-7890</p>
                <div class="error-message" id="phone-error" hidden></div>
            </div>

            <div class="form-actions">
                <button type="submit">Send Support Request</button>
            </div>
        </form>

        <div id="form-status" role="status" class="visually-hidden"></div>
    </main>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const statusRegion = document.getElementById('form-status');

            form.addEventListener('submit', (event) => {
                event.preventDefault();

                // Reset previous errors
                const errorMessages = form.querySelectorAll('.error-message');
                errorMessages.forEach(msg => {
                    msg.hidden = true;
                    msg.textContent = '';
                });

                const inputs = form.querySelectorAll('input');
                inputs.forEach(input => {
                    input.removeAttribute('aria-invalid');
                    if (input.id === 'phone') {
                        input.setAttribute('aria-describedby', 'phone-helper');
                    } else {
                        input.removeAttribute('aria-describedby');
                    }
                });

                const errors = [];

                // Validate Full Name
                const nameInput = document.getElementById('full-name');
                if (!nameInput.value.trim()) {
                    errors.push({
                        id: 'full-name',
                        errorId: 'name-error',
                        message: 'Error: Full Name is required.'
                    });
                }

                // Validate Email
                const emailInput = document.getElementById('email');
                if (!emailInput.value.trim()) {
                    errors.push({
                        id: 'email',
                        errorId: 'email-error',
                        message: 'Error: Email Address is required.'
                    });
                } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput.value)) {
                    errors.push({
                        id: 'email',
                        errorId: 'email-error',
                        message: 'Error: Please enter a valid email address.'
                    });
                }

                if (errors.length > 0) {
                    errors.forEach((error, index) => {
                        const input = document.getElementById(error.id);
                        const errorDiv = document.getElementById(error.errorId);

                        input.setAttribute('aria-invalid', 'true');

                        let describedBy = error.errorId;
                        if (input.id === 'phone') {
                            describedBy += ' phone-helper';
                        }
                        input.setAttribute('aria-describedby', describedBy);

                        errorDiv.textContent = error.message;
                        errorDiv.hidden = false;

                        // Focus the first error
                        if (index === 0) {
                            input.focus();
                        }
                    });

