                    statusRegion.textContent = 'Success: Your support request has been sent.';
                    form.reset();
                    inputs.forEach(input => {
                        input.removeAttribute('aria-invalid');
                        if (input.id === 'phone') {
                            input.setAttribute('aria-describedby', 'phone-helper');
                        } else {
                            input.removeAttribute('aria-describedby');
                        }
                    });
                    alert('Thank you! Your request has been submitted.');
                }
            });
        });
    </script>
