<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Support Contact Form</title>
    <style>
        :root {
            --color-bg: #121212;
            --color-surface: #1e1e1e;
            --color-text: #e0e0e0;
            --color-text-muted: #b0b0b0;
            --color-primary: #bb86fc;
            --color-primary-dark: #3700b3;
            --color-error: #cf6679;
            --color-border: #333333;
            --color-focus: #03dac6;
        }

        * {
            box-sizing: border-box;
        }

        .skip-link {
            position: absolute;
            top: -40px;
            left: 0;
            background: var(--color-primary);
            color: #000;
            padding: 8px;
            z-index: 100;
            transition: top 0.2s;
            text-decoration: none;
            font-weight: bold;
        }

        .skip-link:focus {
            top: 0;
        }

        body {
            background-color: var(--color-bg);
            color: var(--color-text);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            line-height: 1.5;
            margin: 0;
            padding: 2rem;
            display: flex;
            justify-content: center;
            align-items: flex-start;
            min-height: 100vh;
        }

        main {
            max-width: 500px;
            width: 100%;
            background-color: var(--color-surface);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
        }

        h1 {
            margin-top: 0;
            color: var(--color-primary);
        }

        .description {
            margin-bottom: 1.5rem;
            color: var(--color-text-muted);
        }

        .required-note {
            font-size: 0.875rem;
            color: var(--color-text-muted);
            margin-bottom: 1.5rem;
        }

        .form-field {
            margin-bottom: 1.5rem;
        }

        label {
            display: block;
            margin-bottom: 0.5rem;
            font-weight: 600;
        }

        input {
            width: 100%;
            padding: 0.75rem;
            background-color: #2c2c2c;
            border: 1px solid var(--color-border);
            border-radius: 4px;
            color: var(--color-text);
            font-size: 1rem;
            transition: border-color 0.2s, box-shadow 0.2s;
        }

        input:focus {
            outline: none;
            border-color: var(--color-focus);
            box-shadow: 0 0 0 2px var(--color-focus);
        }

        input[aria-invalid="true"] {
            border-color: var(--color-error);
        }

        input[aria-invalid="true"]:focus {
            box-shadow: 0 0 0 2px var(--color-error);
        }

        .helper-text {
            font-size: 0.875rem;
            color: var(--color-text-muted);
            margin-top: 0.25rem;
        }

        .error-message {
            color: var(--color-error);
            font-size: 0.875rem;
            margin-top: 0.25rem;
            font-weight: 600;
            min-height: 1.25rem;
        }

        .form-actions {
            margin-top: 2rem;
        }

        button {
            background-color: var(--color-primary);
            color: #000000;
            border: none;
            padding: 0.75rem 1.5rem;
            font-size: 1rem;
            font-weight: 700;
            border-radius: 4px;
            cursor: pointer;
            transition: background-color 0.2s, color 0.2s;
        }

        button:hover {
            background-color: var(--color-primary-dark);
            color: #ffffff;
        }

        button:focus {
            outline: none;
            box-shadow: 0 0 0 3px var(--color-focus);
        }

        .visually-hidden {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            border: 0;
        }

        @media (forced-colors: active) {
            input:focus, button:focus {
                outline: 2px solid Highlight;
            }
            button {
                border: 1px solid ButtonBorder;
            }
        }
    </style>
</head>
<body>
    <a href="#main-content" class="skip-link">Skip to main content</a>
    <main id="main-content">
        <h1>Support Contact Form</h1>
        <p class="description">Please fill out the form below to get in touch with our support team.</p>
        <p class="required-note">Fields marked with an asterisk (<span aria-hidden="true">*</span>) are required.</p>

        <form id="contact-form" novalidate>
            <div class="form-field">
                <label for="full-name">Full Name <span aria-hidden="true">*</span></label>
                <input type="text" id="full-name" name="full-name" required autocomplete="name">
                <div class="error-message" id="name-error" hidden></div>
            </div>

            <div class="form-field">
                <label for="email">Email Address <span aria-hidden="true">*</span></label>
                <input type="email" id="email" name="email" required autocomplete="email">
                <div class="error-message" id="email-error" hidden></div>
            </div>

            <div class="form-field">
                <label for="phone">Phone Number (Optional)</label>
                <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-helper">
                <p id="phone-helper" class="helper-text">Expected format: +1-123-456-7890</p>
                <div class="error-message" id="phone-error" hidden></div>
            </div>

            <div class="form-actions">
                <button type="submit">Send Support Request</button>
            </div>
        </form>

        <div id="form-status" role="status" class="visually-hidden"></div>
    </main>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const statusRegion = document.getElementById('form-status');

            form.addEventListener('submit', (event) => {
                event.preventDefault();

                // Reset previous errors
                const errorMessages = form.querySelectorAll('.error-message');
                errorMessages.forEach(msg => {
                    msg.hidden = true;
                    msg.textContent = '';
                });

                const inputs = form.querySelectorAll('input');
                inputs.forEach(input => {
                    input.removeAttribute('aria-invalid');
                    if (input.id === 'phone') {
                        input.setAttribute('aria-describedby', 'phone-helper');
                    } else {
                        input.removeAttribute('aria-describedby');
                    }
                });

                const errors = [];

                // Validate Full Name
                const nameInput = document.getElementById('full-name');
                if (!nameInput.value.trim()) {
                    errors.push({
                        id: 'full-name',
                        errorId: 'name-error',
                        message: 'Error: Full Name is required.'
                    });
                }

                // Validate Email
                const emailInput = document.getElementById('email');
                if (!emailInput.value.trim()) {
                    errors.push({
                        id: 'email',
                        errorId: 'email-error',
                        message: 'Error: Email Address is required.'
                    });
                } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput.value)) {
                    errors.push({
                        id: 'email',
                        errorId: 'email-error',
                        message: 'Error: Please enter a valid email address.'
                    });
                }

                if (errors.length > 0) {
                    errors.forEach((error, index) => {
                        const input = document.getElementById(error.id);
                        const errorDiv = document.getElementById(error.errorId);

                        input.setAttribute('aria-invalid', 'true');

                        let describedBy = error.errorId;
                        if (input.id === 'phone') {
                            describedBy += ' phone-helper';
                        }
                        input.setAttribute('aria-describedby', describedBy);

                        errorDiv.textContent = error.message;
                        errorDiv.hidden = false;

                        // Focus the first error
                        if (index === 0) {
                            input.focus();
                        }
                    });

                    // We move focus to the first error, so we don't announce via status region
                    // to avoid competing announcements (per WCAG 4.1.3 advice).
                    statusRegion.textContent = '';
                } else {
                    statusRegion.textContent = 'Success: Your support request has been sent.';
                    form.reset();
                    inputs.forEach(input => {
                        input.removeAttribute('aria-invalid');
                        if (input.id === 'phone') {
                            input.setAttribute('aria-describedby', 'phone-helper');
                        } else {
                            input.removeAttribute('aria-describedby');
                        }
                    });
                    alert('Thank you! Your request has been submitted.');
                }
            });
        });
    </script>
</body>
</html>
